parameters.jsCode:
// Получаем входящие данные от предыдущего узла
const items = $input.all();
const output = [];

// Список колонок, которые НЕ нужно разворачивать (метаданные)
const excludeKeys = [
  "row_number",
  "from instruments sheet *Instrument Vender",
  "*Access type ",
  "*",
  "IT Admin comment for onboarding *",
  "IT Admin comment for offboarding *"
];

for (const item of items) {
  const row = item.json;
  const accessType = (row["*Access type "] || "").trim();

  if (!accessType) continue;

  // Проходим по всем свойствам объекта (строки таблицы)
  for (const key in row) {
    // Пропускаем мета-колонки и ищем только те, что содержат разделитель '*'
    if (!excludeKeys.includes(key) && key.includes('*')) {
      const parts = key.split('*');
      const t1aer = parts[0].trim(); // Например, "Employees" или "Non-Employees"
      const employeeType = parts[1].trim(); // Например, "Contractors"

      // Значение доступа (например, "Default", "No", "By request")
      let accessVal = (row[key] || "").trim();

      // Вычисляем Employee_PD (Yes для Employees, No для Non-Employees)
      const t1aerPd = (t1aer === "Employees") ? "Yes" : "No";

      output.push({
        json: {
          "Access type": accessType,
          "Employee type": employeeType,
          "Employee": t1aer,
          "Access": accessVal,
          "Employee_PD": t1aerPd
        }
      });
    }
  }
}

return output;
